  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:
    """
    Transform the raw dataframe into the analysis-ready dataframe.

    New columns produced (and used by the model):
      - dyslexia_bin: binary dyslexia indicator (1 = dyslexia, 0 = no dyslexia)
      - log_speed: natural log of speed (speed clipped to avoid log(0))
      - num_words_c, Flesch_Kincaid_c, age_c, img_width_c: mean-centered continuous controls
      - device, page_id, uuid, english_native converted to categorical dtype

    Rows with missing key variables (speed, reader_view, dyslexia info) are dropped.
    """
    df = df.copy()

    # Create or coerce dyslexia_bin: prefer existing column, otherwise derive from 'dyslexia'
    if 'dyslexia_bin' in df.columns:
        df['dyslexia_bin'] = pd.to_numeric(df['dyslexia_bin'], errors='coerce')
    else:
        # If 'dyslexia' exists, map 0 -> 0, 1 or 2 -> 1
        if 'dyslexia' in df.columns:
            df['dyslexia_bin'] = np.where(pd.to_numeric(df['dyslexia'], errors='coerce') >= 1, 1, 0)
        else:
            # If neither column exists, create NA column (will be dropped below)
            df['dyslexia_bin'] = np.nan

    # Ensure reader_view exists and is integer 0/1
    if 'reader_view' in df.columns:
        df['reader_view'] = pd.to_numeric(df['reader_view'], errors='coerce').astype('Int64')
    else:
        df['reader_view'] = pd.NA

    # Keep only rows with necessary vars: speed, reader_view, dyslexia_bin
    df['speed'] = pd.to_numeric(df['speed'], errors='coerce')
    df = df.dropna(subset=['speed', 'reader_view', 'dyslexia_bin'])

    # Defensive: fill/convert types for controls
    if 'correct_rate' in df.columns:
        df['correct_rate'] = pd.to_numeric(df['correct_rate'], errors='coerce')
    else:
        df['correct_rate'] = np.nan

    if 'retake_trial' in df.columns:
        df['retake_trial'] = pd.to_numeric(df['retake_trial'], errors='coerce').fillna(0)
    else:
        df['retake_trial'] = 0

    # Clip speed to avoid log(0) and extreme negatives; then log-transform
    df['speed'] = df['speed'].clip(lower=1e-3)
    df['log_speed'] = np.log(df['speed'])

    # Mean-center continuous predictors if present
    continuous_to_center = ['num_words', 'Flesch_Kincaid', 'age', 'img_width']
    for col in continuous_to_center:
        if col in df.columns:
            centered = col + '_c'
            df[centered] = pd.to_numeric(df[col], errors='coerce') - pd.to_numeric(df[col], errors='coerce').mean()
        else:
            # create NaN-centered column to keep column names consistent
            df[col + '_c'] = np.nan

    # Ensure categorical variables have category dtype
    for cat in ['device', 'page_id', 'uuid', 'english_native']:
        if cat in df.columns:
            df[cat] = df[cat].astype('category')
        else:
            # create placeholder category with single NaN category if missing
            df[cat] = pd.Categorical(df.get(cat, pd.Series([pd.NA]*len(df))))

    # Ensure dyslexia_bin and reader_view are numeric 0/1
    df['dyslexia_bin'] = pd.to_numeric(df['dyslexia_bin'], errors='coerce').fillna(0).astype(int)
    df['reader_view'] = pd.to_numeric(df['reader_view'], errors='coerce').fillna(0).astype(int)

    # If correct_rate has missing values, fill with column mean (conservative)
    if df['correct_rate'].isnull().any():
        df['correct_rate'] = df['correct_rate'].fillna(df['correct_rate'].mean())

    # Final drop: keep rows with no missing values for model columns
    model_cols = [
        'log_speed', 'reader_view', 'dyslexia_bin', 'num_words_c', 'Flesch_Kincaid_c', 'age_c',
        'device', 'english_native', 'retake_trial', 'correct_rate', 'img_width_c', 'page_id', 'uuid'
    ]
    df = df.dropna(subset=['log_speed', 'reader_view', 'dyslexia_bin]) if False else df
    # The above line is intentionally inert (keeps earlier careful NA handling). Instead, ensure minimal NA removal:
    df = df.dropna(subset=['log_speed', 'reader_view', 'dyslexia_bin'])

    # Return transformed dataframe
    return df
